import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    """Enhanced heuristic minimizing transition, turn, and energy risks while rewarding depot proximity under battery stress."""
    dist_term = 1.0 / (dist_m + 1.0)
    turn_penalty = 0.1 * np.clip(turn_deg, 0, 360)
    norm_len = swath_len_m / 500.0
    energy_cost = (dist_m + swath_len_m + depot_dist_m) * (1.0 - energy_left_frac) * 10.0
    base_score = dist_term - turn_penalty - norm_len - energy_cost
    if not fits:
        return np.full_like(base_score, 1e-3, dtype=float)
    risk_bonus = np.where(energy_left_frac < 0.25, 2.0 * (0.25 - energy_left_frac) / 0.25, 0.0)
    depot_proximity = np.where(energy_left_frac < 0.3, 1.0 / (depot_dist_m + 1.0), 0.0)
    return np.maximum(base_score + risk_bonus + depot_proximity, 1e-4)
